def default_tool_parser(raw_tool_calls):
    tool_calls = []
    invalid_tool_calls = []

    for raw_tool_call in raw_tool_calls:
        try:
            function = raw_tool_call.get("function")

            # Validate function object
            if not isinstance(function, dict):
                invalid_tool_calls.append(
                    invalid_tool_call(
                        name=None,
                        args=None,
                        id=raw_tool_call.get("id"),
                        error="Tool call function must be a dict",
                    )
                )
                continue

            function_name = function.get("name")
            function_args = function.get("arguments")

            # Validate required fields
            if function_name is None:
                invalid_tool_calls.append(
                    invalid_tool_call(
                        name=None,
                        args=function_args,
                        id=raw_tool_call.get("id"),
                        error="Missing function name",
                    )
                )
                continue

            if function_args is None:
                invalid_tool_calls.append(
                    invalid_tool_call(
                        name=function_name,
                        args=None,
                        id=raw_tool_call.get("id"),
                        error="Missing function arguments",
                    )
                )
                continue

            parsed_args = json.loads(function_args)

            tool_calls.append(
                tool_call(
                    name=function_name,
                    args=parsed_args,
                    id=raw_tool_call.get("id"),
                )
            )

        except json.JSONDecodeError as e:
            invalid_tool_calls.append(
                invalid_tool_call(
                    name=function.get("name") if isinstance(function, dict) else None,
                    args=function.get("arguments") if isinstance(function, dict) else None,
                    id=raw_tool_call.get("id"),
                    error=str(e),
                )
            )

    return tool_calls, invalid_tool_calls

**Workaround: monkey-patch `BaseTool.model_dump` for clean JSON serialization in traces**

Tested against `langchain==1.2.9`, `langchain-core==1.2.12`, `langsmith==0.7.1`, `pydantic==2.12.4`.

We hit this in production with a LangGraph agent traced by LangSmith. Our agent mixes native `@tool`-decorated tools with MCP tools. The MCP tools serialize fine (their `args_schema` is already a plain dict), but native tools produce `"<class 'pydantic._internal._model_construction.ModelMetaclass'>"` instead of the actual JSON Schema in the trace's `extra.invocation_params.tools[]` array.

Until this is fixed upstream, we apply a monkey-patch at import time. It intercepts `mode="json"` only (so `mode="python"` is unchanged), excludes `args_schema` / `func` / `coroutine` from Pydantic's serialization, then re-adds them in JSON-safe form: `args_schema` becomes a `model_json_schema()` dict (or passes through if already a dict, e.g. MCP tools), and `func`/`coroutine` become their `__qualname__`. Caller-supplied `include=` and `exclude=` are honored on the re-add so the patch doesn't override what the caller asked for.

```python
from langchain_core.tools import BaseTool
from pydantic import BaseModel

_ORIGINAL_MODEL_DUMP = BaseTool.model_dump
_NON_SERIALIZABLE_FIELDS = frozenset({"args_schema", "func", "coroutine"})

def _patched_model_dump(self, *, mode="python", **kwargs):
    if mode != "json":
        return _ORIGINAL_MODEL_DUMP(self, mode=mode, **kwargs)

    include = kwargs.get("include", None)
    caller_exclude = kwargs.pop("exclude", None) or set()
    caller_exclude_keys = (
        set(caller_exclude.keys())
        if isinstance(caller_exclude, dict)
        else set(caller_exclude)
    )
    if isinstance(caller_exclude, dict):
        exclude = {**caller_exclude, **{f: True for f in _NON_SERIALIZABLE_FIELDS}}
    else:
        exclude = set(caller_exclude) | _NON_SERIALIZABLE_FIELDS
    result = _ORIGINAL_MODEL_DUMP(self, mode=mode, exclude=exclude, **kwargs)

    # Honor caller's include= (only re-add what they requested) and
    # exclude= (don't re-add what they explicitly excluded).
    if include is not None:
        fields_to_add = _NON_SERIALIZABLE_FIELDS & (
            set(include) if not isinstance(include, dict) else set(include.keys())
        )
    else:
        fields_to_add = set(_NON_SERIALIZABLE_FIELDS)
    fields_to_add -= caller_exclude_keys

    exclude_none = kwargs.get("exclude_none", False)

    if "args_schema" in fields_to_add:
        if self.args_schema is not None:
            if isinstance(self.args_schema, type) and issubclass(self.args_schema, BaseModel):
                result["args_schema"] = self.args_schema.model_json_schema()
            else:
                result["args_schema"] = self.args_schema
        elif not exclude_none:
            result["args_schema"] = None

    for field in ("func", "coroutine"):
        if field not in fields_to_add:
            continue
        value = getattr(self, field, None)
        if value is not None:
            result[field] = getattr(value, "__qualname__", str(value))
        elif not exclude_none:
            result[field] = None

    return result

BaseTool.model_dump = _patched_model_dump
```

This aligns with the proposed fix in the issue description (`field_serializer` decorators on `BaseTool`). We'll remove the patch once that ships in `langchain-core`. Sharing in case others need a stopgap.

_Edit: updated to honor caller-provided `exclude=` for the three non-serializable fields (was previously force-re-adding them)._

